from __future__ import annotations

import re

_TEMPLATE_PATTERNS = [
    re.compile(r"^\{\{\s*[\w.\-]+\s*\}\}$"),
    re.compile(r"^\$\{\s*[\w.\-]+(:-[^}]*)?\s*\}$"),
    re.compile(r"^<[\w \-]+>$"),
    re.compile(r"^%[\w\-]+%$"),
]

_PLACEHOLDER_WORDS = frozenset({
    "changeme", "changethis", "changeit",
    "dummy", "example", "sample", "placeholder",
    "redacted", "replaceme", "insertkeyhere",
    "enteryourkey", "enterapikey", "addyourkey",
    "yourkeyhere", "yourapikey", "yourapikeyhere",
    "yourtoken", "yourtokenhere", "yoursecret",
    "yoursecrethere", "yourpassword", "yourpasswordhere",
    "todo", "fixme", "tbd", "na", "notavailable",
    "none", "null", "undefined", "nil", "empty",
    "test", "testing", "fake", "foo", "bar",
    "foobar", "xxx", "yyy", "zzz", "asdf",
    "password", "password123", "secret", "token",
    "apikey", "api", "key", "credential",
    "credentials", "auth", "authtoken", "accesstoken",
    "awstoken", "awssecret", "awskey", "mytoken",
    "mysecret", "mypassword", "mykey", "myapikey",
    "secretkey", "secretvalue", "secrethere",
})

_GENERIC_SECRET_WORD = re.compile(r"^[a-z]+(?:_[a-z]+)*$")
_SECRET_VOCABULARY = ["token", "secret", "password", "passwd", "pwd", "key", "credential", "auth", "apikey"]


def _normalize(s: str) -> str:
    return "".join(c for c in s.lower() if c.isalnum())


def _all_same_char(s: str) -> bool:
    return len(s) >= 2 and len(set(s)) == 1


def looks_like_placeholder(val: str) -> bool:
    trimmed = val.strip()
    if not trimmed:
        return False

    for pat in _TEMPLATE_PATTERNS:
        if pat.match(trimmed):
            return True

    normalized = _normalize(trimmed)
    if normalized in _PLACEHOLDER_WORDS:
        return True

    if _all_same_char(normalized):
        return True

    lower = trimmed.lower()
    if _GENERIC_SECRET_WORD.match(lower):
        for word in _SECRET_VOCABULARY:
            if word in lower:
                return True

    return False
